const base=[40,42,43,44,45];
const show=()=>{const sizes=[...base,+hot.value].sort((a,b)=>a-b),n=sizes.length,median=(sizes[n/2-1]+sizes[n/2])/2,relative=median*(+factor.value),effective=Math.max(relative,+threshold.value),skew=(+hot.value)>relative&&(+hot.value)>(+threshold.value),pieces=skew?Math.ceil((+hot.value)/(+advisory.value)):1,piece=(+hot.value)/pieces,after=skew?Math.max(45,piece):+hot.value;world.textContent='Partitions MB: '+sizes.join(', ')+'\nMedian: '+median.toFixed(1)+' MB\nRelative boundary: '+relative.toFixed(1)+' MB\nAbsolute boundary: '+threshold.value+' MB\nMust exceed both → effective boundary: '+effective.toFixed(1)+' MB\nSkewed? '+(skew?'yes':'no')+'\nModeled pieces: '+pieces+' × '+piece.toFixed(1)+' MB\nLargest task input after adaptation: '+after.toFixed(1)+' MB'};[hot,factor,threshold,advisory].forEach(e=>e.oninput=show);show();
function paintConcept(){

const vh=+hot.value,vm=43.5,vr=vm*+factor.value,vt=+threshold.value,vs=vh>vr&&vh>vt,vn=vs?Math.ceil(vh/+advisory.value):1,vp=vh/vn;
const bar=(name,val)=>'<div style="margin:8px 0">'+name+': '+val.toFixed(1)+' MB<div style="height:15px;background:#142b32;border:1px solid #708f98"><div style="height:100%;width:'+val/1200*100+'%;background:#9bd2b4"></div></div></div>';
vscene.innerHTML='<p>Fixed ruler: 0–1200 MB per task. Relative gate '+vr.toFixed(1)+' MB; absolute gate '+vt+' MB. The hot partition must pass <b>both</b>.</p>'+bar('Before: largest of the five normal partitions',45)+bar('Before: hot partition',vh)+'<div style="border-top:2px dashed #aecbd0;padding-top:8px"><b>'+ (vs?'SPLIT: '+vn+' pieces':'NO SPLIT: at least one gate blocks adaptation')+'</b>'+bar('After: each hot-partition piece',vp)+bar('After: largest normal partition',45)+'</div><p>New maximum: <b>'+Math.max(45,vp).toFixed(1)+' MB</b>. '+vn+' pieces still contain '+vh+' MB in total; the work is redistributed, not deleted.</p>';

}
["hot", "factor", "threshold", "advisory"].forEach(id=>{const el=document.getElementById(id);["onclick","oninput","onchange"].forEach(kind=>{const prior=el[kind];if(prior)el[kind]=function(...args){const result=prior.apply(this,args);paintConcept();return result;};});});paintConcept();

let next=0,owner=null,aToken=null,bToken=null,maxAccepted=0,value='initial',log=[];
const show=()=>world.textContent='Lease owner: '+(owner||'none')+'\nA token: '+(aToken??'none')+'; B token: '+(bToken??'none')+'\nResource max accepted: '+maxAccepted+'\nResource value: '+value+'\n\n'+log.join('\n');
const write=(who,token,val)=>{if(token===null){log.push(who+' has no token');return}if(fencing.checked&&token<maxAccepted){log.push('REJECT '+who+' token '+token+' < '+maxAccepted);return}maxAccepted=Math.max(maxAccepted,token);value=val;log.push('ACCEPT '+who+' token '+token)};
grantA.onclick=()=>{aToken=++next;owner='A';log.push('A granted token '+aToken);show()};expireA.onclick=()=>{if(owner==='A')owner=null;log.push('A lease expired; A process may still resume');show()};grantB.onclick=()=>{bToken=++next;owner='B';log.push('B granted token '+bToken);show()};writeB.onclick=()=>{write('B',bToken,'snapshot-B');show()};resumeA.onclick=()=>{write('A',aToken,'stale-snapshot-A');show()};reset.onclick=()=>{next=0;owner=null;aToken=null;bToken=null;maxAccepted=0;value='initial';log=[];show()};fencing.oninput=show;show();
function paintConcept(){

vscene.innerHTML='<div style="border:1px dashed #a6c6ce;padding:10px"><b>Lease ledger:</b> current owner '+(owner||'none')+'<br>Expiry changes this ledger; it does not erase a token held by a paused process.</div><div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:12px"><div>Worker A holds <b>'+ (aToken??'no token')+'</b><br>Delayed write ↓</div><div>Worker B holds <b>'+(bToken??'no token')+'</b><br>New write ↓</div></div><div style="border:3px double #ffce9a;padding:12px;margin-top:12px"><b>Storage gate: '+(fencing.checked?'reject token &lt; '+maxAccepted:'NO fencing check')+'</b><p>Newest accepted token: '+maxAccepted+'</p><p>Persisted value: <strong>'+value+'</strong></p></div><p>Last transition: <b>'+(log[log.length-1]||'No write yet')+'</b></p>';

}
["fencing", "grantA", "expireA", "grantB", "writeB", "resumeA", "reset"].forEach(id=>{const el=document.getElementById(id);["onclick","oninput","onchange"].forEach(kind=>{const prior=el[kind];if(prior)el[kind]=function(...args){const result=prior.apply(this,args);paintConcept();return result;};});});paintConcept();

const tenants=1000;const show=()=>{const n=+cells.value,cellImpact=Math.ceil(tenants/n),affected=shared.checked?tenants:cellImpact;world.textContent='Tenants: '+tenants+'\nCells: '+n+'\nModeled tenants per cell: ≤ '+cellImpact+'\nFailure: '+(shared.checked?'shared dependency':'one cell')+'\nMaximum affected in this model: '+affected+' ('+(affected/tenants*100).toFixed(1)+'%)\nDeployment/observability units: '+n+'\n\nQuestion: which supposedly shared path bypasses this boundary?'};[cells,shared].forEach(e=>e.oninput=show);show();
function paintConcept(){

const vn=+cells.value,vEach=Math.ceil(1000/vn);
vscene.innerHTML='<div style="border:3px '+(shared.checked?'solid':'dashed')+' #ffb398;padding:10px;text-align:center"><b>Shared critical dependency: '+(shared.checked?'FAILED':'available')+'</b><br>'+(shared.checked?'↓ failure reaches every cell ↓':'A local failure stays below this boundary in the toy model.')+'</div><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(105px,1fr));gap:8px;margin-top:14px">'+Array.from({length:vn},(_,i)=>{const count=Math.max(0,Math.min(vEach,1000-i*vEach)),failed=shared.checked||i===0;return '<div style="border:2px '+(failed?'solid':'dashed')+' '+(failed?'#ffb398':'#9bceb0')+';padding:10px">Cell '+(i+1)+'<br><b>'+count+' tenants</b><br>'+(failed?'✕ interrupted':'✓ serving')+'</div>'}).join('')+'</div><p>One local failure affects at most '+vEach+' tenants. Shared failure affects all 1,000. Separate deployments do not isolate a common database, identity path, or control dependency automatically.</p>';

}
["cells", "shared"].forEach(id=>{const el=document.getElementById(id);["onclick","oninput","onchange"].forEach(kind=>{const prior=el[kind];if(prior)el[kind]=function(...args){const result=prior.apply(this,args);paintConcept();return result;};});});paintConcept();

const show=()=>{const presented=aud.value||'catalog.example',accepted=strict.checked?presented==='catalog.example':true;if(!accepted){world.textContent='MCP decision: REJECT\nReason: token audience '+presented+' is not catalog.example\nUpstream call: none';return}const upstream=strict.checked?'aud=storage.api; scope=read; principal=catalog-server':'same client token (aud='+presented+')';world.textContent='MCP decision: ACCEPT\nAudience validation: '+(strict.checked?'passed':'not enforced')+'\nUpstream credential: '+upstream+'\nRisk: '+(strict.checked?'separate identities and least-privilege review remain':'token passthrough / confused-deputy boundary')};run.onclick=show;[aud,strict].forEach(e=>e.oninput=show);show();
function paintConcept(){

const va=aud.value||'catalog.example',vAccepted=!strict.checked||va==='catalog.example';
vscene.innerHTML='<div style="border:1px solid #9abdc5;padding:10px">Client envelope<br><b>aud = '+va+'</b></div><p>↓ present to catalog boundary</p><div style="border:3px double #ffcd98;padding:12px"><b>catalog.example</b><br>'+ (strict.checked?'Audience comparison: '+va+' = catalog.example? '+(vAccepted?'YES':'NO → STOP'):'Audience check skipped → ACCEPT')+'</div>'+(vAccepted?'<p>↓ '+(strict.checked?'obtain a separate credential':'forward SAME envelope')+'</p><div style="border:1px solid #9abdc5;padding:10px"><b>storage.api boundary</b><br>'+(strict.checked?'NEW token: aud=storage.api<br>scope=read · principal=catalog-server':'PASSTHROUGH token: aud='+va+'<br>Catalog identity and upstream authorization are not separated.')+'</div>':'<p><b>Upstream path is closed. No storage request occurs.</b></p>')+'<p>This sketch models audience boundaries; real validation also checks signature, issuer, expiry, scope and authorization. It does not mint live credentials.</p>';

}
["aud", "strict", "run"].forEach(id=>{const el=document.getElementById(id);["onclick","oninput","onchange"].forEach(kind=>{const prior=el[kind];if(prior)el[kind]=function(...args){const result=prior.apply(this,args);paintConcept();return result;};});});paintConcept();

const history=[100,98,102,101,99,100,101],planned=[0,0,1,0,0,1,0];const show=()=>{const mean=history.reduce((a,b)=>a+b,0)/history.length,forecast=planned.map(x=>mean+(include.checked?x*(+effect.value):0)),total=forecast.reduce((a,b)=>a+b,0);world.textContent='History: '+history.join(', ')+'\nFuture planned-backfill flags: '+planned.join(', ')+'\nMode: '+(include.checked?'target history + known future covariate':'history-only baseline')+'\nForecast: '+forecast.map(x=>x.toFixed(1)).join(', ')+'\nIllustrative intervals: '+forecast.map(x=>'['+(x-15).toFixed(0)+','+(x+15).toFixed(0)+']').join(' ')+'\n7-day total: '+total.toFixed(1)+'\n\nThis calculator is not TimesFM-3.'};[include,effect].forEach(e=>e.oninput=show);show();
function paintConcept(){

const vm=history.reduce((a,b)=>a+b,0)/history.length;
vscene.innerHTML='<p>Future days; fixed ruler 0–200 units. Outlined bar = history-only mean '+vm.toFixed(1)+'. Filled bar = selected forecast.</p><div style="display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:5px">'+planned.map((flag,i)=>{const value=vm+(include.checked?flag*+effect.value:0);return '<div style="text-align:center;font-size:.82rem"><div style="height:150px;position:relative;border-bottom:1px solid #afcad1"><div style="position:absolute;bottom:0;left:5%;width:90%;height:'+vm/200*100+'%;border:2px dashed #bedadf;box-sizing:border-box"></div><div style="position:absolute;bottom:0;left:25%;width:50%;height:'+value/200*100+'%;background:#79baa3"></div></div><b>D'+(i+1)+'</b><br>'+value.toFixed(0)+'<br>'+(flag?'backfill':'normal')+'</div>'}).join('')+'</div><p>'+ (include.checked?'Only days 3 and 6 rise, by '+effect.value+' units each.':'The history-only baseline cannot see the two planned backfills.')+' Future measurements would be leakage; the flags here represent a plan known before prediction.</p>';

}
["include", "effect"].forEach(id=>{const el=document.getElementById(id);["onclick","oninput","onchange"].forEach(kind=>{const prior=el[kind];if(prior)el[kind]=function(...args){const result=prior.apply(this,args);paintConcept();return result;};});});paintConcept();
